import react from 'react';

function ModifyTicketModal(){
    return(
        <div className="modalBackground">
           <div className="modalContainer">
            <div className="title">
                <h1>Hibajegy módosítása</h1>
            </div>
            <div className="body">
               
            </div>
            <div className="footer">
                <button className="closeBtn">Bezárás</button>
                <button className="saveBtn">Módosítás</button>
            </div>
           </div>
        </div>
    )
}

export default ModifyTicketModal;
